interface UserSuccess {
    success: true;
    user: { name: string };
}

interface UserError {
    success: false;
    error: string;
}

type UserResponse = UserSuccess | UserError;

// Custom Type Guard
const isSuccess = (response: UserResponse): response is UserSuccess => {
    return response.success === true;
};

const handleResponse = (res: UserResponse): void => {
    if (isSuccess(res)) {
        console.log(`Success: Welcome ${res.user.name}`);
    } else {
        console.error(`Error: ${res.error}`);
    }
};

handleResponse({ success: true, user: { name: 'Alex' } });

type Action =
    | { type: 'FETCH_START' }
    | { type: 'FETCH_SUCCESS'; payload: string[] }
    | { type: 'FETCH_ERROR'; error: string };

const reducer = (state: string[], action: Action): string[] => {
    switch (action.type) {
        case 'FETCH_START':
            return [];
        case 'FETCH_SUCCESS':
            return action.payload;
        case 'FETCH_ERROR':
            console.error(action.error);
            return [];
    }
};

const state = reducer([], { type: 'FETCH_SUCCESS', payload: ['React', 'TypeScript'] });
console.log('State Updated:', state);

