class ApiClient {
    constructor(private baseUrl: string) {}

    async get<T>(endpoint: string): Promise<T> {
        const res = await fetch(`${this.baseUrl}${endpoint}`);
        if (!res.ok) throw new Error(`HTTP Error ${res.status}`);
        return res.json() as Promise<T>;
    }
}

