enum TaskStatus {
    PENDING = 'PENDING',
    IN_PROGRESS = 'IN_PROGRESS',
    COMPLETED = 'COMPLETED'
}

interface Task {
    readonly id: number;
    title: string;
    status: TaskStatus;
}

type CreateTaskDTO = Omit<Task, 'id'>;

class TaskEngine {
    private tasks: Task[] = [];
    private nextId: number = 1;

    createTask(dto: CreateTaskDTO): Task {
        const task: Task = {
            id: this.nextId++,
            ...dto
        };
        this.tasks.push(task);
        return task;
    }

    getTasksByStatus(status: TaskStatus): Task[] {
        return this.tasks.filter(t => t.status === status);
    }
}

const engine = new TaskEngine();
engine.createTask({ title: 'Deploy TS Compiler', status: TaskStatus.IN_PROGRESS });
engine.createTask({ title: 'Write Type Guards', status: TaskStatus.COMPLETED });

console.log('In Progress:', engine.getTasksByStatus(TaskStatus.IN_PROGRESS));
